/**
 * DRM 加密系统 - 用于保护上传的照片
 * 使用 AES-GCM 加密算法
 */

class DRMEncryptor {
    constructor() {
        this.algorithm = 'AES-GCM';
        this.keyLength = 256; // 256 位密钥
        this.version = '1.0';
    }

    /**
     * 生成加密密钥
     * 使用浏览器生成的随机数
     */
    generateKey() {
        const arrayBuffer = new Uint8Array(this.keyLength / 8);
        window.crypto.getRandomValues(arrayBuffer);
        return btoa(String.fromCharCode(...arrayBuffer));
    }

    /**
     * 从 base64 字符串解码密钥
     */
    decodeKey(keyBase64) {
        const binaryString = atob(keyBase64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes;
    }

    /**
     * 加密图片数据
     * @param {string} imageData - Base64 编码的图片数据
     * @param {string} keyBase64 - Base64 编码的密钥
     * @returns {object} 包含加密数据和元数据
     */
    encrypt(imageData, keyBase64) {
        const key = this.decodeKey(keyBase64);
        const iv = window.crypto.getRandomValues(new Uint8Array(12)); // 12 字节 IV

        try {
            const encryptedContent = window.crypto.subtle.encrypt(
                {
                    name: this.algorithm,
                    iv: iv
                },
                key,
                this.decodeImageData(imageData)
            );

            const encryptedArray = new Uint8Array(encryptedContent);
            const encryptedBase64 = btoa(String.fromCharCode(...Array.from(encryptedArray)));

            return {
                encryptedData: encryptedBase64,
                iv: Array.from(iv).map(b => b.toString(16).padStart(2, '0')).join(''),
                timestamp: Date.now(),
                version: this.version
            };
        } catch (error) {
            console.error('加密失败:', error);
            throw error;
        }
    }

    /**
     * 解密图片数据
     * @param {string} encryptedData - Base64 编码的加密数据
     * @param {string} ivHex - 十六进制格式的 IV
     * @param {string} keyBase64 - Base64 编码的密钥
     * @returns {string} 解密后的 Base64 图片数据
     */
    async decrypt(encryptedData, ivHex, keyBase64) {
        const key = this.decodeKey(keyBase64);
        const iv = new Uint8Array(ivHex.match(/.{1,2}/g).map(byte => parseInt(byte, 16)));

        try {
            const encryptedArray = Uint8Array.from(atob(encryptedData), c => c.charCodeAt(0));
            const decryptedContent = await window.crypto.subtle.decrypt(
                {
                    name: this.algorithm,
                    iv: iv
                },
                key,
                encryptedArray
            );

            const decryptedArray = new Uint8Array(decryptedContent);
            const decryptedString = String.fromCharCode(...Array.from(decryptedArray));
            return btoa(decryptedString);
        } catch (error) {
            console.error('解密失败:', error);
            throw new Error('解密失败：密钥错误或数据损坏');
        }
    }

    /**
     * 将图片数据转换为 ArrayBuffer
     */
    decodeImageData(imageData) {
        const base64 = imageData.split(',')[1];
        const binaryString = atob(base64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes;
    }

    /**
     * 将 ArrayBuffer 转换为 Base64
     */
    encodeImageData(arrayBuffer) {
        const bytes = new Uint8Array(arrayBuffer);
        let binary = '';
        for (let i = 0; i < bytes.byteLength; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return btoa(binary);
    }

    /**
     * 验证加密数据版本
     */
    validateVersion(encryptedData) {
        const version = encryptedData.version;
        if (version !== this.version) {
            console.warn(`版本不匹配：当前 ${this.version}, 加密数据 ${version}`);
            return false;
        }
        return true;
    }
}

/**
 * 照片 DRM 管理器
 */
class PhotoDRMManager {
    constructor() {
        this.encryptor = new DRMEncryptor();
        this.storageKey = 'campusPhotosDRM';
        this.keyStorageKey = 'drmEncryptionKey';
        this.init();
    }

    /**
     * 初始化：检查或生成密钥
     */
    init() {
        const storedKey = localStorage.getItem(this.keyStorageKey);
        if (!storedKey) {
            const newKey = this.encryptor.generateKey();
            localStorage.setItem(this.keyStorageKey, newKey);
            console.log('DRM 密钥已生成（首次使用）');
        }
    }

    /**
     * 获取当前密钥
     */
    getKey() {
        return localStorage.getItem(this.keyStorageKey);
    }

    /**
     * 上传加密照片
     * @param {File} file - 图片文件
     * @returns {object} 加密后的照片对象
     */
    async uploadPhoto(file) {
        try {
            // 读取文件为 Base64
            const reader = new FileReader();
            await new Promise((resolve, reject) => {
                reader.onload = (e) => resolve(e.target.result);
                reader.onerror = (e) => reject(new Error('读取文件失败'));
                reader.readAsDataURL(file);
            });

            const imageData = reader.result;
            const key = this.getKey();

            // 加密图片
            const encrypted = this.encryptor.encrypt(imageData, key);

            // 创建照片对象
            const photo = {
                id: Date.now().toString(36) + Math.random().toString(36).substr(2),
                originalName: file.name.replace(/\.[^/.]+$/, ''),
                title: file.name.replace(/\.[^/.]+$/, ''),
                date: new Date().toLocaleString('zh-CN', {
                    year: 'numeric',
                    month: '2-digit',
                    day: '2-digit',
                    hour: '2-digit',
                    minute: '2-digit'
                }),
                encryptedData: encrypted,
                encryptionKey: key,
                version: this.encryptor.version
            };

            // 保存到本地存储
            this.savePhotos([photo]);

            return photo;
        } catch (error) {
            console.error('上传加密失败:', error);
            throw error;
        }
    }

    /**
     * 渲染加密照片
     */
    renderPhotos() {
        const gallery = document.getElementById('gallery');
        if (!gallery) return;

        gallery.innerHTML = '';

        const photos = this.getPhotos();
        if (photos.length === 0) {
            gallery.innerHTML = '<p style="text-align:center;padding:20px;color:#ccc;">暂无照片</p>';
            return;
        }

        photos.forEach((photo, index) => {
            const photoCard = document.createElement('div');
            photoCard.className = 'photo-card';
            photoCard.innerHTML = `
                <div class="photo-content">
                    <img src="${photo.url}" alt="${photo.title}" onerror="this.style.display='none';this.nextElementSibling.style.display='block'">
                    <div class="photo-error" style="display:none;text-align:center;padding:20px;">
                        <p>需要授权才能查看</p>
                        <button onclick="authorizePhoto('${photo.id}')">获取授权</button>
                    </div>
                </div>
                <div class="photo-info">
                    <h3>${photo.title}</h3>
                    <p>${photo.date}</p>
                    <button class="delete-btn" onclick="deletePhoto('${photo.id}')">删除</button>
                </div>
            `;
            gallery.appendChild(photoCard);
        });
    }

    /**
     * 获取照片列表
     */
    getPhotos() {
        return JSON.parse(localStorage.getItem(this.storageKey)) || [];
    }

    /**
     * 保存照片列表
     */
    savePhotos(photos) {
        localStorage.setItem(this.storageKey, JSON.stringify(photos));
    }

    /**
     * 删除照片
     */
    deletePhoto(photoId) {
        if (!confirm('确定要删除这张照片吗？')) return;

        const photos = this.getPhotos();
        const filteredPhotos = photos.filter(p => p.id !== photoId);
        this.savePhotos(filteredPhotos);

        // 清除密钥（可选）
        localStorage.removeItem(this.keyStorageKey);

        this.renderPhotos();
    }

    /**
     * 授权查看照片
     */
    authorizePhoto(photoId) {
        const photos = this.getPhotos();
        const photo = photos.find(p => p.id === photoId);

        if (photo) {
            // 解密并显示
            const decrypted = this.encryptor.decrypt(
                photo.encryptedData.encryptedData,
                photo.encryptedData.iv,
                photo.encryptionKey
            );

            const blob = btoa(decrypted);
            const byteString = atob(blob);
            const buffer = new ArrayBuffer(byteString.length);
            const intArray = new Uint8Array(buffer);
            for (let i = 0; i < byteString.length; i++) {
                intArray[i] = byteString.charCodeAt(i);
            }

            const blobObject = new Blob([buffer], { type: 'image/jpeg' });
            const url = URL.createObjectURL(blobObject);

            // 显示图片
            const img = document.querySelector(`img[src*="${photoId}"]`);
            if (img) {
                img.src = url;
                img.style.display = 'block';
                img.nextElementSibling.style.display = 'none';
            }
        }
    }

    /**
     * 导出所有照片（带 DRM）
     */
    exportPhotos() {
        const photos = this.getPhotos();
        const key = this.getKey();

        const exportData = {
            version: this.encryptor.version,
            timestamp: Date.now(),
            photos: photos.map(p => ({
                id: p.id,
                title: p.title,
                date: p.date,
                encryptedData: p.encryptedData,
                encryptionKey: p.encryptionKey
            }))
        };

        const blob = new Blob([JSON.stringify(exportData)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `campus_photos_${new Date().toISOString().split('T')[0]}.drm`;
        a.click();
    }
}

// 全局实例
